export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    try {
      if (request.method === 'GET' && url.pathname === '/') return htmlResponse(renderApp(env));
      if (request.method === 'GET' && url.pathname === '/manifest.webmanifest') return jsonResponse(manifest(url.origin), 200, {'Cache-Control':'public,max-age=300'});
      if (request.method === 'GET' && url.pathname === '/icon.svg') return svgResponse(iconSvg());
      if (request.method === 'GET' && url.pathname === '/sw.js') return jsResponse(serviceWorkerJs(), {'Cache-Control':'no-cache'});
      if (request.method === 'GET' && url.pathname === '/health') return healthResponse(env);
      if (request.method === 'POST' && url.pathname.startsWith('/api/')) return await handleApi(request, env, url.pathname.slice(5));
      return jsonResponse({ok:false,error:{code:'NOT_FOUND',message:'Route not found.'}},404);
    } catch (error) {
      return jsonResponse({ok:false,error:{code:'WORKER_ERROR',message:safeMessage(error)}},500);
    }
  }
};

function renderApp(env) {
  const clientId = String(env.GOOGLE_CLIENT_ID || '');
  return __APP_HTML__.replaceAll('__GOOGLE_CLIENT_ID__', htmlAttr(clientId)).replaceAll('__APP_VERSION__', APP_VERSION);
}

async function handleApi(request, env, encodedAction) {
  assertConfig(env);
  const action = decodeURIComponent(encodedAction || '').trim();
  if (!ALLOWED_ACTIONS.has(action)) return jsonResponse({ok:false,error:{code:'NOT_FOUND',message:'WORKER '+APP_VERSION+': acción no permitida: '+action}},404);
  const auth = request.headers.get('Authorization') || '';
  if (!auth.startsWith('Bearer ')) return jsonResponse({ok:false,error:{code:'UNAUTHORIZED',message:'Google credential required.'}},401);
  const credential = auth.slice(7).trim();
  let identity;
  try { identity = await verifyGoogleIdToken(credential, String(env.GOOGLE_CLIENT_ID)); }
  catch (e) { return jsonResponse({ok:false,error:{code:'UNAUTHORIZED',message:'Google identity could not be verified.'}},401); }
  const raw = await request.text();
  if (raw.length > 1024 * 1024) return jsonResponse({ok:false,error:{code:'VALIDATION_ERROR',message:'Request body is too large.'}},413);
  let crmRequest = {};
  if (raw) { try { crmRequest = JSON.parse(raw); } catch { return jsonResponse({ok:false,error:{code:'VALIDATION_ERROR',message:'Invalid JSON body.'}},400); } }
  const workerRequestId = crypto.randomUUID();
  const envelope = await buildSignedEnvelope(env, action, crmRequest, identity.email, workerRequestId);
  let upstream;
  try {
    upstream = await fetch(String(env.OVCRM_API_V2_URL), {
      method:'POST', headers:{'Content-Type':'application/json; charset=utf-8'}, body:JSON.stringify(envelope), redirect:'follow'
    });
  } catch (e) {
    return jsonResponse({ok:false,worker_request_id:workerRequestId,error:{code:'SERVER_BUSY',message:'No se pudo contactar API V2.'}},503);
  }
  let payload;
  const text = await upstream.text();
  try { payload = JSON.parse(text); }
  catch { return jsonResponse({ok:false,worker_request_id:workerRequestId,error:{code:'INTERNAL_ERROR',message:'API V2 devolvió una respuesta inválida.'}},502); }
  if (payload && payload.ok === false) {
    if(payload.error?.code==='NOT_FOUND'&&/action is not allowed/i.test(payload.error.message||'')){
      payload.error.message='API rechazó '+action+' (Worker '+APP_VERSION+'). Revisar rutas de la API en la URL configurada en OVCRM_API_V2_URL.';
      payload.error.details={...(payload.error.details||{}),origin:'API',action,worker_version:APP_VERSION};
    }
    return jsonResponse(payload, apiStatus(payload.error && payload.error.code));
  }
  return jsonResponse(payload, upstream.ok ? 200 : 502, {'Cache-Control':'no-store'});
}

function assertConfig(env) {
  if (String(env.OVCRM_WORKER_ENVIRONMENT || 'STAGING') !== 'STAGING') throw new Error('Worker environment must be STAGING.');
  if (!String(env.OVCRM_API_V2_URL || '').startsWith('https://')) throw new Error('OVCRM_API_V2_URL missing.');
  if (String(env.OVCRM_API_V2_INTERNAL_HMAC_SECRET || '').length < 32) throw new Error('OVCRM_API_V2_INTERNAL_HMAC_SECRET missing/short.');
  if (!String(env.GOOGLE_CLIENT_ID || '').includes('.apps.googleusercontent.com')) throw new Error('GOOGLE_CLIENT_ID missing.');
}

async function buildSignedEnvelope(env, action, request, email, workerRequestId) {
  const payload = {action, request: request || {}};
  const server_context = {worker_environment:'STAGING',worker_request_id:workerRequestId,identity:{provider:'GOOGLE',verified:true,email:String(email).toLowerCase()}};
  const body_hash = await sha256Hex(canonicalJson({payload,server_context}));
  const timestamp = Math.floor(Date.now()/1000);
  const nonce = randomNonce();
  const canonical = ['v1','POST',INTERNAL_PATH,String(timestamp),nonce,body_hash].join('\n');
  const signature = await hmacBase64Url(String(env.OVCRM_API_V2_INTERNAL_HMAC_SECRET), canonical);
  return {payload,server_context,auth:{version:'v1',method:'POST',path:INTERNAL_PATH,timestamp,nonce,body_hash,signature}};
}

async function verifyGoogleIdToken(jwt, expectedAudience) {
  const parts = String(jwt || '').split('.');
  if (parts.length !== 3) throw new Error('bad jwt');
  const header = JSON.parse(utf8FromBase64Url(parts[0]));
  const claims = JSON.parse(utf8FromBase64Url(parts[1]));
  if (header.alg !== 'RS256' || !header.kid) throw new Error('bad alg');
  const now = Math.floor(Date.now()/1000);
  if (!['https://accounts.google.com','accounts.google.com'].includes(claims.iss)) throw new Error('bad issuer');
  const audOk = Array.isArray(claims.aud) ? claims.aud.includes(expectedAudience) : claims.aud === expectedAudience;
  if (!audOk) throw new Error('bad audience');
  if (!claims.exp || Number(claims.exp) <= now - 30) throw new Error('expired');
  if (claims.nbf && Number(claims.nbf) > now + 60) throw new Error('not yet valid');
  if (claims.iat && Number(claims.iat) > now + 60) throw new Error('bad iat');
  if (!(claims.email_verified === true || claims.email_verified === 'true') || !claims.email) throw new Error('unverified email');
  const jwks = await googleJwks();
  const jwk = (jwks.keys || []).find(k => k.kid === header.kid && k.kty === 'RSA');
  if (!jwk) throw new Error('kid missing');
  const key = await crypto.subtle.importKey('jwk', jwk, {name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'}, false, ['verify']);
  const signed = new TextEncoder().encode(parts[0]+'.'+parts[1]);
  const sig = bytesFromBase64Url(parts[2]);
  const ok = await crypto.subtle.verify({name:'RSASSA-PKCS1-v1_5'}, key, sig, signed);
  if (!ok) throw new Error('bad signature');
  return {email:String(claims.email).trim().toLowerCase(),sub:String(claims.sub||'')};
}

async function googleJwks() {
  const cache = caches.default;
  const key = new Request('https://ovcrm.invalid/google-jwks-cache-v1');
  let cached = await cache.match(key);
  if (cached) return cached.json();
  const r = await fetch('https://www.googleapis.com/oauth2/v3/certs', {headers:{'Accept':'application/json'}});
  if (!r.ok) throw new Error('jwks fetch failed');
  const body = await r.text();
  const response = new Response(body,{headers:{'Content-Type':'application/json','Cache-Control':'public,max-age=1800'}});
  await cache.put(key,response.clone());
  return JSON.parse(body);
}

function canonicalJson(value) {
  if (value === undefined) return 'null';
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '['+value.map(canonicalJson).join(',')+']';
  return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+canonicalJson(value[k])).join(',')+'}';
}
async function sha256Hex(text) { const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)); return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''); }
async function hmacBase64Url(secret,text) { const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']); const sig=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(text)); return base64Url(new Uint8Array(sig)); }
function randomNonce(){const b=new Uint8Array(24);crypto.getRandomValues(b);return base64Url(b)}
function base64Url(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function bytesFromBase64Url(s){s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';const b=atob(s),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a}
function utf8FromBase64Url(s){return new TextDecoder().decode(bytesFromBase64Url(s))}
function apiStatus(code){return ({UNAUTHORIZED:401,FORBIDDEN:403,NOT_FOUND:404,VALIDATION_ERROR:400,TEMPORAL_VALIDATION_ERROR:400,NEXT_ACTION_REQUIRED:400,QUALIFICATION_REQUIRED:400,INVALID_STATE:409,PROJECT_REQUIRED:400,BUSINESS_HOURS_NOT_CONFIGURED:400,VERSION_REQUIRED:400,INGEST_CONFLICT:409,APPOINTMENT_REQUIRES_OP:400,DUPLICATE_KEY:409,DUPLICATE_REQUEST_CONFLICT:409,VERSION_CONFLICT:409,SERVER_BUSY:503,SERVER_MISCONFIGURED:500,SAFETY_BLOCK:403,DATA_INTEGRITY_ERROR:409})[code]||500}
function safeMessage(e){const m=String(e && e.message || 'Worker error.');return /secret|token|signature/i.test(m)?'Worker configuration error.':m}
function htmlAttr(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function htmlResponse(body){return new Response(body,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','Cross-Origin-Opener-Policy':'same-origin-allow-popups','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline' https://accounts.google.com/gsi/client; style-src 'self' 'unsafe-inline' https://accounts.google.com/gsi/style; frame-src https://accounts.google.com/gsi/ https://accounts.google.com/; img-src 'self' data: https://*.googleusercontent.com; connect-src 'self' https://accounts.google.com https://www.googleapis.com; base-uri 'none'; frame-ancestors 'none'; object-src 'none'"}})}
function jsonResponse(v,status=200,headers={}){return new Response(JSON.stringify(v),{status,headers:{'Content-Type':'application/json; charset=utf-8','X-Content-Type-Options':'nosniff',...headers}})}
function jsResponse(body,headers={}){return new Response(body,{headers:{'Content-Type':'application/javascript; charset=utf-8',...headers}})}
function svgResponse(body){return new Response(body,{headers:{'Content-Type':'image/svg+xml','Cache-Control':'public,max-age=86400'}})}
function healthResponse(env){return jsonResponse({ok:true,name:'OV CRM Worker V2',version:APP_VERSION,environment:String(env.OVCRM_WORKER_ENVIRONMENT||'STAGING'),config:{api_url_configured:String(env.OVCRM_API_V2_URL||'').startsWith('https://'),hmac_secret_configured:String(env.OVCRM_API_V2_INTERNAL_HMAC_SECRET||'').length>=32,google_client_id_configured:String(env.GOOGLE_CLIENT_ID||'').includes('.apps.googleusercontent.com')},external_sends:{capi:false,whatsapp:false}})}
function manifest(origin){return {name:'OV Real Estate CRM V2',short_name:'OV CRM V2',start_url:'/',scope:'/',display:'standalone',background_color:'#f4f4f5',theme_color:'#111111',lang:'es-MX',icons:[{src:'/icon.svg',sizes:'any',type:'image/svg+xml',purpose:'any maskable'}]}}
function iconSvg(){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#111"/><text x="256" y="235" text-anchor="middle" fill="#fff" font-family="Arial,sans-serif" font-size="126" font-weight="700">OV</text><text x="256" y="322" text-anchor="middle" fill="#fff" font-family="Arial,sans-serif" font-size="43" letter-spacing="5">REAL ESTATE</text></svg>`}
function serviceWorkerJs(){return `const C='ovcrm-v2-shell-2111';self.addEventListener('install',e=>e.waitUntil(caches.open(C).then(c=>c.addAll(['/','/manifest.webmanifest','/icon.svg']))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('ovcrm-v2-shell-')&&k!==C).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.pathname.startsWith('/api/')||u.pathname==='/health')return;e.respondWith(fetch(e.request).then(r=>{const x=r.clone();caches.open(C).then(c=>c.put(e.request,x));return r}).catch(()=>caches.match(e.request)))})`}
